class Solution:
    def maximumBags(self, capacity: list[int], rocks: list[int], additionalRocks: int) -> int:
        need = sorted(c - r for c, r in zip(capacity, rocks))    # rocks missing from each bag; O(n log n)
        full = 0
        for d in need:                     # cheapest bags first
            if d > additionalRocks:
                break                      # every later bag needs at least as much
            additionalRocks -= d
            full += 1                      # bags with d == 0 are counted for free
        return full

